        updateDojang(id, data, shouldNotify = true) {
            const list = this.getDojangs();
            const idx = list.findIndex(d => d.id === id);
            if (idx !== -1) {
                list[idx] = { ...list[idx], ...data };
                localStorage.setItem('tkd_dojangs', JSON.stringify(list));
                if (shouldNotify) this.notify();
            }
        }

        getAthletes() {
            const list = JSON.parse(localStorage.getItem('tkd_athletes')) || [];
            const seen = new Set();
            const unique = [];
            let hasDups = false;
            list.forEach(a => {
                if (!a) return;
                const nameKey = (a.name || '').trim().toLowerCase();
                const tournId = (a.registeredTournaments && a.registeredTournaments[0]) || 'tourn-state-2026';
                const dedupeKey = `${nameKey}___${a.gender || ''}___${tournId}`;
                if (nameKey && seen.has(dedupeKey)) {
                    hasDups = true;
                    return; // drop duplicate athlete record
                }
                if (nameKey) seen.add(dedupeKey);
                unique.push(a);
            });
            if (hasDups) {
                try { localStorage.setItem('tkd_athletes', JSON.stringify(unique)); } catch (e) {}
            }
            return unique.map(a => ({
                discipline: a.discipline || 'Kyorugi',
                competitionFormat: a.competitionFormat || (a.category?.includes('Group-4') ? 'Group-4' : 'Official'),
                group4Category: a.group4Category || (a.category?.includes('Group-4') ? (a.category.match(/[UA]-\d+/) || [null])[0] : null),
                ...a
            }));
        }
        getAthlete(id) { return this.getAthletes().find(a => a.id === id || a.athleteId === id) || null; }

        addAthlete(aData) {
            const list = this.getAthletes();
            const inputName = (aData.name || '').trim().toLowerCase();
            const tournId = (aData.registeredTournaments && aData.registeredTournaments[0]) || aData.tournId || this.getSelectedTournamentId() || 'tourn-state-2026';
            
            // If athlete with same id or name already exists in this tournament/club, update it to prevent duplicates
            const existingIdx = list.findIndex(a => {
                if (!a) return false;
                if (aData.id && (a.id === aData.id || a.athleteId === aData.id)) return true;
                if (aData.athleteId && (a.athleteId === aData.athleteId || a.id === aData.athleteId)) return true;
                const matchName = inputName && (a.name || '').trim().toLowerCase() === inputName;
                if (matchName && aData.phone && a.phone && a.phone.includes(aData.phone.slice(-8))) return true;
                return false;
            });

            if (existingIdx !== -1) {
                list[existingIdx] = { 
                    ...list[existingIdx], 
                    ...aData,
                    tournId: aData.tournId || list[existingIdx].tournId || tournId,
                    registeredTournaments: aData.registeredTournaments || list[existingIdx].registeredTournaments || [tournId]
                };
                localStorage.setItem('tkd_athletes', JSON.stringify(list));
                this.notify();
                try {
                    fetch(`/api/athletes/${list[existingIdx].id}`, {
                        method: 'PATCH',
                        headers: { 'Content-Type': 'application/json' },
                        body: JSON.stringify(list[existingIdx])
                    }).catch(() => {});
                } catch (e) {}
                return list[existingIdx];
            }

            const newA = {
                id: aData.id || ('ath-' + Date.now().toString(36)),
                athleteId: aData.athleteId || ('ATH-' + Math.floor(100000 + Math.random() * 900000)),
                discipline: aData.discipline || 'Kyorugi',
                competitionFormat: aData.competitionFormat || 'Official',
                group4Category: aData.group4Category || null,
                status: aData.status || 'Pending',
                paymentStatus: aData.paymentStatus || 'Pending',
                feeStatus: aData.feeStatus || 'Pending',
                avatar: aData.avatar || '',
                photo: aData.photo || '',
                aadharDoc: aData.aadharDoc || '',
                birthCertDoc: aData.birthCertDoc || '',
                docStatus: aData.docStatus || (aData.aadharDoc && aData.birthCertDoc ? 'Pending' : (aData.aadharDoc || aData.birthCertDoc ? 'Pending' : 'Missing')),
                docVerifiedBy: aData.docVerifiedBy || '',
                docVerifiedAt: aData.docVerifiedAt || '',
                docNotes: aData.docNotes || '',
                dojangName: aData.dojangName || 'Individual Competitor',
                dojangId: aData.dojangId || 'ind-competitor',
                dojangCode: aData.dojangCode || 'IND',
                tournId: tournId,
                registeredTournaments: aData.registeredTournaments || [tournId],
                stats: { matches: 0, wins: 0, ko: 0, ranking: 'Competitor' },
                ...aData
            };
            list.push(newA);
            localStorage.setItem('tkd_athletes', JSON.stringify(list));
            this.notify();
            try {
                fetch('/api/athletes', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify(newA)
                }).catch(() => {});
            } catch (e) {}
            return newA;
        }

        updateAthlete(id, data, shouldNotify = true) {
            const list = this.getAthletes();
            const idx = list.findIndex(a => a.id === id || a.athleteId === id);
            if (idx !== -1) {
                list[idx] = { ...list[idx], ...data };
                localStorage.setItem('tkd_athletes', JSON.stringify(list));
                if (shouldNotify) this.notify();
                if (typeof window.syncTournamentAthletesToDraws === 'function') {
                    try { window.syncTournamentAthletesToDraws(false); } catch (e) {}
                }
                try {
                    fetch(`/api/athletes/${list[idx].id}`, {
                        method: 'PATCH',
                        headers: { 'Content-Type': 'application/json' },
                        body: JSON.stringify(data)
                    }).catch(() => {});
                } catch (e) {}
            }
        }

        updateAthleteWeighIn(athId, status, measuredWt = null) {
            const list = this.getAthletes();
            const idx = list.findIndex(a => a.id === athId || a.athleteId === athId);
            if (idx !== -1) {
                const wt = (measuredWt !== null && !isNaN(measuredWt) && measuredWt > 0) ? parseFloat(measuredWt) : (list[idx].measuredWeight || list[idx].weight);
                list[idx] = {
                    ...list[idx],
                    status: status,
                    weighInStatus: status,
                    measuredWeight: wt,
                    weight: wt
                };
                localStorage.setItem('tkd_athletes', JSON.stringify(list));
                this.notify();
                // Real-time synchronization with Draws engine: only scale-passed athletes qualify
                if (typeof window.syncTournamentAthletesToDraws === 'function') {
                    try {
                        window.syncTournamentAthletesToDraws(false);
                    } catch (e) {
                        console.warn('Could not auto-sync draws on weigh-in update:', e);
                    }
                }
            }
        }

