    function printAllAthleteCards(param = null, competitionTitle = null) {
        const activeTourn = store.getActiveTournament();
        const effectiveTitle = competitionTitle || activeTourn?.title || 'State Level Open Taekwondo Championship 2026';
        let athletes = [];
        let coaches = [];

        if (Array.isArray(param)) {
            athletes = param;
            coaches = store.getCoaches();
        } else if (typeof param === 'string' && param) {
            const allTournAthletes = activeTourn ? store.getAthletesForTournament(activeTourn.id) : store.getAthletes();
            athletes = allTournAthletes.filter(a => a.dojangId === param);
            coaches = store.getCoaches().filter(c => c.dojangId === param);
        } else {
            athletes = activeTourn ? store.getAthletesForTournament(activeTourn.id) : store.getAthletes();
            coaches = store.getCoaches();
        }

        if (coaches.length === 0 && athletes.length === 0) {
            showToast('No registered passes found to print.', 'info');
            return;
        }

        const allPagesHtml = `
            ${coaches.map(c => `
                <div class="tkd-print-card-wrapper">
                    ${renderCoachIdCardHtml(c, effectiveTitle)}
                </div>
            `).join('')}
            ${athletes.map(a => `
                <div class="tkd-print-card-wrapper">
                    ${renderAthleteIdCardHtml(a, effectiveTitle)}
                </div>
            `).join('')}
        `;

        executePrintPassHtml(allPagesHtml, true);
    }

