    function getWeightOptions(category, gender) {
        const cat = TKD_WEIGHT_CATEGORIES[category];
        if (!cat) return '<option value="">— Select Category & Gender first —</option>';
        const weights = cat[gender] || [];
        return weights.map(w => `<option value="${w}">${w}</option>`).join('');
    }

    function updateWeightCategoryDropdown() {
        const category = document.getElementById('reg-p-category')?.value;
        const gender   = document.getElementById('reg-p-gender')?.value;
        const wSelect  = document.getElementById('reg-p-weightclass');
        const wWrapper = document.getElementById('reg-p-weightclass-wrapper');
        if (!wSelect || !wWrapper) return;

        if (category && gender) {
            wSelect.innerHTML = getWeightOptions(category, gender);
            wWrapper.style.display = 'block';
        } else {
            wWrapper.style.display = 'none';
        }
    }

    // --- Strict Phone & Password Security Helpers ---
    function bindStrictPhoneInput(el) {
        if (!el) return;
        el.addEventListener('input', (e) => {
            e.target.value = e.target.value.replace(/\D/g, '').slice(0, 10);
        });
    }

    function validateStrictPhone(phone) {
        const clean = (phone || '').replace(/\D/g, '');
        return clean.length === 10;
    }

    function setupPasswordSecurity(pwdInput, toggleBtn, meterBar, feedbackEl) {
        if (!pwdInput) return;
        if (toggleBtn) {
            toggleBtn.addEventListener('click', () => {
                const isPass = pwdInput.type === 'password';
                pwdInput.type = isPass ? 'text' : 'password';
                toggleBtn.innerHTML = isPass ? '<i class="fa-regular fa-eye-slash"></i>' : '<i class="fa-regular fa-eye"></i>';
            });
        }
        if (meterBar && feedbackEl) {
            pwdInput.addEventListener('input', () => {
                const val = pwdInput.value;
                let score = 0;
                if (val.length >= 8) score += 25;
                if (/[a-z]/.test(val) && /[A-Z]/.test(val)) score += 25;
                if (/\d/.test(val)) score += 25;
                if (/[^a-zA-Z0-9]/.test(val)) score += 25;

                meterBar.style.width = score + '%';
                if (score <= 25) {
                    meterBar.style.backgroundColor = '#f43f5e';
                    feedbackEl.innerHTML = '<span class="text-rose-400 font-semibold">Weak (min 8 chars, uppercase, number & symbol)</span>';
                } else if (score <= 50) {
                    meterBar.style.backgroundColor = '#fb923c';
                    feedbackEl.innerHTML = '<span class="text-amber-400 font-semibold">Moderate</span>';
                } else if (score <= 75) {
                    meterBar.style.backgroundColor = '#facc15';
                    feedbackEl.innerHTML = '<span class="text-amber-300 font-semibold">Good</span>';
                } else {
                    meterBar.style.backgroundColor = '#10b981';
                    feedbackEl.innerHTML = '<span class="text-emerald-400 font-semibold flex items-center gap-1"><i class="fa-solid fa-shield-check"></i> Strong &amp; Secure</span>';
                }
            });
        }
    }

    function validateStrongPassword(val) {
        if (!val || val.length < 6) return false;
        return true;
    }

    function formatSingleDate(dateRaw) {
        if (!dateRaw) return 'TBD';
        const parts = String(dateRaw).trim().split('-');
        if (parts.length === 3) {
            const y = parts[0];
            const m = parseInt(parts[1], 10) - 1;
            const d = parseInt(parts[2], 10);
            const months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
            const mon = months[m] || parts[1];
            const padD = String(d).padStart(2, '0');
            return `${padD} ${mon} ${y}`;
        }
        return dateRaw;
    }

    function formatTournamentDates(startRaw, endRaw) {
        if (!startRaw && !endRaw) return 'TBD';
        const sStr = String(startRaw || '').trim();
        const eStr = String(endRaw || '').trim();

        if (!eStr || sStr === eStr) {
            return formatSingleDate(sStr);
        }

        const sParts = sStr.split('-');
        const eParts = eStr.split('-');

        if (sParts.length === 3 && eParts.length === 3) {
            const sY = parseInt(sParts[0], 10);
            const sM = parseInt(sParts[1], 10) - 1;
            const sD = parseInt(sParts[2], 10);

            const eY = parseInt(eParts[0], 10);
            const eM = parseInt(eParts[1], 10) - 1;
            const eD = parseInt(eParts[2], 10);

            const months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
            const sMon = months[sM] || sParts[1];
            const eMon = months[eM] || eParts[1];
            const padD = (d) => String(d).padStart(2, '0');

            // Same year and same month: e.g. "15 - 17 Sep 2026"
            if (sY === eY && sM === eM) {
                return `${padD(sD)} - ${padD(eD)} ${sMon} ${sY}`;
            }
            // Same year, different month: e.g. "28 Sep - 02 Oct 2026"
            if (sY === eY) {
                return `${padD(sD)} ${sMon} - ${padD(eD)} ${eMon} ${sY}`;
            }
            // Different years: e.g. "30 Dec 2026 - 02 Jan 2027"
            return `${padD(sD)} ${sMon} ${sY} - ${padD(eD)} ${eMon} ${eY}`;
        }

        return `${sStr} - ${eStr}`;
    }

