    // Modal for Official Academy Invoice & Financial Statement
    function openInvoiceModal(dojang, athletes, tourn, totalFees, paidAmount = 0, balanceAmount = 0) {
        if (dojang && dojang.id) {
            openAcademyFeeReceiptModal(dojang.id);
            return;
        }
        const mc = document.getElementById('modal-container');
        if (!mc) return;

        const feePerAthlete = tourn ? (tourn.feePerAthlete || 1500.00) : 1500.00;
        const calcTotal = totalFees || (athletes.length * feePerAthlete);
        const paidAthletes = athletes.filter(a => a.paymentStatus === 'Paid');
        const unpaidAthletes = athletes.filter(a => a.paymentStatus !== 'Paid');
        const calcPaid = paidAmount || (paidAthletes.length * feePerAthlete);
        const calcBal = (balanceAmount !== undefined && balanceAmount !== null && balanceAmount > 0) ? balanceAmount : (unpaidAthletes.length * feePerAthlete);
        const isPaidInFull = unpaidAthletes.length === 0 && athletes.length > 0;
        const tournTitle = tourn ? tourn.title : 'State Level Open Taekwondo Championship 2026';

        mc.innerHTML = `
            <div class="tkd-modal-backdrop animate-fade-in" id="modal-invoice">
                <div class="tkd-modal-card max-w-lg">
                    <button class="tkd-modal-close" id="btn-close-inv">&times;</button>
                    <div class="flex items-center gap-2 mb-2 pe-8">
                        <span class="tkd-badge ${isPaidInFull ? 'tkd-badge-green' : 'tkd-badge-blue'} font-bold">
                            <i class="fa-solid ${isPaidInFull ? 'fa-circle-check' : 'fa-receipt'} me-1"></i>
                            ${isPaidInFull ? 'OFFICIAL RECEIPT' : 'OFFICIAL INVOICE'}
                        </span>
                        <span class="text-xs text-slate-600 font-mono">INV-ACAD-${dojang.uid || '9681'}</span>
                    </div>
                    <h3 class="text-xl font-bold text-slate-900">${tournTitle}</h3>
                    <p class="text-xs text-slate-600 mb-4">Official Academy Registration Breakdown &amp; Financial Statement</p>

                    <div class="p-4 bg-slate-100 rounded-xl border border-slate-200 text-xs space-y-2.5 mb-4">
                        <div class="flex justify-between text-slate-600">
                            <span>Academy / Club:</span>
                            <span class="font-bold text-slate-900">${dojang.name} (${dojang.shortCode})</span>
                        </div>
                        <div class="flex justify-between text-slate-600">
                            <span>Per Athlete Entry Fee:</span>
                            <span class="font-mono font-bold text-slate-900">₹ ${feePerAthlete.toLocaleString('en-IN')}</span>
                        </div>
                        <div class="flex justify-between text-slate-600">
                            <span>Total Registered Competitors:</span>
                            <span class="font-mono font-bold text-slate-900">${athletes.length} Fighters</span>
                        </div>
                        <div class="flex justify-between text-slate-600">
                            <span>Total Entry Fees Payable:</span>
                            <span class="font-mono font-bold text-slate-900">₹ ${calcTotal.toLocaleString('en-IN')}</span>
                        </div>
                        <div class="flex justify-between text-slate-600">
                            <span>Amount Paid in Full:</span>
                            <span class="font-mono font-bold text-emerald-400">₹ ${calcPaid.toLocaleString('en-IN')} (${paidAthletes.length} Paid)</span>
                        </div>
                        <div class="flex justify-between text-slate-600">
                            <span>Coaching Passes Fee:</span>
                            <span class="font-mono text-emerald-400 font-bold">COMPLIMENTARY (₹ 0)</span>
                        </div>
                        <div class="flex justify-between font-bold text-slate-900 pt-2.5 border-t border-slate-200 text-sm">
                            <span>${isPaidInFull ? 'Total Settled Amount:' : 'Remaining Balance Due:'}</span>
                            <span class="font-mono ${isPaidInFull ? 'text-emerald-400' : 'text-amber-400'} font-black text-base">
                                ₹ ${(isPaidInFull ? calcTotal : calcBal).toLocaleString('en-IN')}
                            </span>
                        </div>
                    </div>

                    <div class="flex gap-2">
                        ${isPaidInFull ? `
                            <button class="tkd-btn tkd-btn-blue flex-1 text-xs font-bold" onclick="printAcademyFeeReceipt('${dojang.id}')">
                                <i class="fa-solid fa-print me-1.5"></i> Print Official Receipt
                            </button>
                        ` : `
                            <button class="tkd-btn tkd-btn-blue flex-1 text-xs font-bold" id="btn-inv-pay-now">
                                <i class="fa-solid fa-lock me-1.5"></i> Pay Balance Online (₹ ${calcBal.toLocaleString('en-IN')})
                            </button>
                            <button class="tkd-btn tkd-btn-outline text-xs" onclick="printAcademyFeeReceipt('${dojang.id}')">
                                <i class="fa-solid fa-print me-1.5"></i> Print Invoice
                            </button>
                        `}
                    </div>
                </div>
            </div>
        `;

        document.getElementById('btn-close-inv')?.addEventListener('click', () => { mc.innerHTML = ''; });
        document.getElementById('btn-inv-pay-now')?.addEventListener('click', () => {
            mc.innerHTML = '';
            openPaymentGatewayModal({
                title: tournTitle,
                subtitle: 'Academy Delegation Remaining Balance',
                payeeName: `${dojang.name} (${dojang.masterName})`,
                divisionName: `${unpaidAthletes.length} Unpaid Competitors • 2 Coaches`,
                amount: calcBal,
                type: 'dojang',
                id: dojang.id,
                onComplete: () => {
                    store.recordDojangPayment(dojang.id, calcBal, 'Online UPI / Card (Bulk)');
                    showToast(`Payment of ₹${calcBal.toLocaleString('en-IN')} successful for ${dojang.name}!`, 'success');
                    window.app.navigate('dashboard');
                }
            });
        });
    }

