    function renderDrawsViewer(container) {
        const user = store.getCurrentUser();
        const tournaments = store.getTournaments();
        const selectedTournId = store.getSelectedTournamentId();
        const activeTourn = store.getTournament(selectedTournId) || tournaments[0] || {};
        const isAdmin = user && user.role === 'admin';
        const roleTitle = isAdmin ? 'Federation Master Admin' : 'Tournament Organizing Committee';

        container.innerHTML = `
            <div class="space-y-4 animate-fade-in w-full py-2" id="draws-console-root">
                <!-- Top Console Header Bar -->
                <div class="bg-white p-4 md:p-5 rounded-2xl border border-slate-200 shadow-sm flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
                    <div>
                        <div class="flex flex-wrap items-center gap-2">
                            <span class="tkd-badge bg-blue-600 text-white text-[10px] font-black uppercase tracking-wider px-2.5 py-1">
                                <i class="fa-solid fa-sitemap me-1.5"></i>Official Draws Engine
                            </span>
                            <span class="tkd-badge bg-amber-100 text-amber-900 border border-amber-300 text-[10px] font-bold px-2 py-0.5">
                                <i class="fa-solid ${isAdmin ? 'fa-crown text-amber-600' : 'fa-user-check text-blue-600'} me-1"></i>${roleTitle}
                            </span>
                            <span class="text-xs text-slate-500 font-semibold hidden sm:inline">
                                • ${activeTourn.title || 'Official Championship'}
                            </span>
                        </div>
                        <h1 class="text-xl md:text-2xl font-black text-slate-900 mt-1 font-heading">
                            Championship Knockout Draws &amp; Ring Allocations
                        </h1>
                        <p class="text-xs text-slate-600 font-medium mt-0.5">
                            Interactive draw trees, Group-4 pools, WT Official weight categories, court ring assignments, and live bout scoring.
                        </p>
                    </div>

                    <div class="flex flex-wrap items-center gap-2 w-full md:w-auto shrink-0">
                        <button id="btn-sync-draws-roster" class="tkd-btn tkd-btn-sm tkd-btn-primary font-bold text-xs shadow-xs cursor-pointer" title="Sync registered athletes from active championship into draws generator">
                            <i class="fa-solid fa-arrows-rotate me-1.5"></i>Sync Athletes from Kyorix Roster
                        </button>
                        <button id="btn-popout-draws" class="tkd-btn tkd-btn-sm tkd-btn-outline font-bold text-xs cursor-pointer" title="Open draws application in full browser window">
                            <i class="fa-solid fa-arrow-up-right-from-square me-1.5 text-blue-600"></i>Fullscreen
                        </button>
                    </div>
                </div>

                <!-- Full Embedded Draws Engine Iframe -->
                <div class="relative w-full bg-slate-900 rounded-2xl overflow-hidden shadow-lg border border-slate-200">
                    <iframe id="tkd-draws-iframe" src="draws-app/index.html?v=452" class="w-full border-0 block bg-slate-950" style="height: calc(100vh - 170px); min-height: 850px;" allow="fullscreen"></iframe>
                </div>
            </div>
        `;

        // Auto-run sync on load so Draws Engine always matches the active tournament roster without manual sync
        if (typeof window.syncTournamentAthletesToDraws === 'function') {
            window.syncTournamentAthletesToDraws(false);
        }

        // Sync Athletes Button Click
        const syncBtn = document.getElementById('btn-sync-draws-roster');
        if (syncBtn) {
            syncBtn.onclick = () => {
                if (typeof window.syncTournamentAthletesToDraws === 'function') {
                    window.syncTournamentAthletesToDraws(true);
                }
            };
        }

        // Popout Fullscreen Button Click
        const popoutBtn = document.getElementById('btn-popout-draws');
        if (popoutBtn) {
            popoutBtn.onclick = () => {
                window.open('draws-app/index.html', '_blank');
            };
        }
    }

    // ========================================================================
        // ========================================================================
    // TOURNAMENT TREE ADVANCEMENT & BRACKET MATCH SCORING HELPERS
    // ========================================================================
    function advanceWalkoversInTree(rounds) {
        if (!rounds || rounds.length === 0) return;
        for (let t = 1; t < rounds.length; t++) {
            for (let m of rounds[t]) {
                m.p1 = null;
                m.p2 = null;
                if (m.status !== 'completed') {
                    m.winnerId = null;
                    m.status = 'pending';
                }
            }
        }
        for (let t = 0; t < rounds.length; t++) {
            let curr = rounds[t], next = rounds[t + 1];
            for (let m of curr) {
                if (t === 0) {
                    if (m.p1 && !m.p2) { m.winnerId = m.p1.id; m.status = 'walkover'; }
                    else if (!m.p1 && m.p2) { m.winnerId = m.p2.id; m.status = 'walkover'; }
                    else if (!m.p1 && !m.p2) { m.status = 'walkover'; }
                }
                if (m.winnerId && next) {
                    let nextM = next[Math.floor(m.matchIndex / 2)];
                    let winnerComp = m.winnerId === m.p1?.id ? m.p1 : m.p2;
                    if (nextM) {
                        if (m.matchIndex % 2 === 0) nextM.p1 = winnerComp;
                        else nextM.p2 = winnerComp;
                    }
                }
            }
        }
        for (let t = 0; t < rounds.length - 1; t++) {
            let next = rounds[t + 1];
            for (let m of next) {
                if (m.status === 'pending') {
                    let topFeeder = rounds[t][m.matchIndex * 2];
                    let btmFeeder = rounds[t][m.matchIndex * 2 + 1];
                    let topActive = topFeeder && (topFeeder.p1 || topFeeder.p2);
                    let btmActive = btmFeeder && (btmFeeder.p1 || btmFeeder.p2);
                    if (m.p1 && !btmActive) { m.winnerId = m.p1.id; m.status = 'walkover'; }
                    else if (m.p2 && !topActive) { m.winnerId = m.p2.id; m.status = 'walkover'; }
                    else if (!topActive && !btmActive) { m.status = 'walkover'; }
                }
            }
        }
        for (let t = 0; t < rounds.length - 1; t++) {
            let curr = rounds[t], next = rounds[t + 1];
            for (let m of curr) {
                if (m.winnerId && next) {
                    let nextM = next[Math.floor(m.matchIndex / 2)];
                    let winnerComp = m.winnerId === m.p1?.id ? m.p1 : m.p2;
                    if (nextM) {
                        if (m.matchIndex % 2 === 0) nextM.p1 = winnerComp;
                        else nextM.p2 = winnerComp;
                    }
                }
            }
        }
    }

    function assignMatchNumbers(rounds) {
        let count = 1;
        for (let r = 0; r < rounds.length; r++) {
            for (let m = 0; m < rounds[r].length; m++) {
                let match = rounds[r][m];
                if (match.status === 'walkover') {
                    match.matchNo = null;
                } else {
                    match.matchNo = count++;
                }
            }
        }
    }

    function applyBracketMatchScore(divId, matchId, winnerId, score1, score2, winType, roundScores) {
        let curBrackets = {};
        try {
            curBrackets = JSON.parse(localStorage.getItem('tkd_brackets_v3') || '{}');
        } catch(e) {}

        const rounds = curBrackets[divId];
        if (!rounds || !Array.isArray(rounds)) return null;

        let targetMatch = null;
        let targetRoundIdx = -1;
        let targetMatchIdx = -1;

        for (let r = 0; r < rounds.length; r++) {
            const idx = rounds[r].findIndex(m => m.id === matchId);
            if (idx !== -1) {
                targetMatch = rounds[r][idx];
                targetRoundIdx = r;
                targetMatchIdx = idx;
                break;
            }
        }

        if (!targetMatch) return null;

        const winner = (winnerId === targetMatch.p1?.id) ? targetMatch.p1 : targetMatch.p2;
        const resolvedWinnerId = winnerId || (winner ? winner.id : targetMatch.p1?.id);

        targetMatch.winnerId = resolvedWinnerId;
        targetMatch.score1 = score1;
        targetMatch.score2 = score2;
        targetMatch.winType = winType || 'WPS';
        targetMatch.roundScores = roundScores;
        targetMatch.status = 'completed';

        // Clear downstream matches if re-scoring previous round
        let rDown = targetRoundIdx, iDown = targetMatchIdx;
        while (rDown < rounds.length - 1) {
            let nextMIdx = Math.floor(iDown / 2);
            let nextMatch = rounds[rDown + 1][nextMIdx];
            if (nextMatch) {
                if (iDown % 2 === 0) nextMatch.p1 = null;
                else nextMatch.p2 = null;
                nextMatch.winnerId = null;
                nextMatch.score1 = null;
                nextMatch.score2 = null;
                nextMatch.winType = null;
                nextMatch.status = 'pending';
            }
            rDown++;
            iDown = nextMIdx;
        }

        // Recalculate tree advancement and numbers
        advanceWalkoversInTree(rounds);
        assignMatchNumbers(rounds);

        // Save to localStorage
        try {
            localStorage.setItem('tkd_brackets_v3', JSON.stringify(curBrackets));
            localStorage.setItem('tkd_match_updated', Date.now().toString());
        } catch(e) {}

        // Notify store if addResult is available
        if (store && typeof store.addResult === 'function') {
            try {
                store.addResult({
                    matchId: matchId,
                    divisionId: divId,
                    winnerId: resolvedWinnerId,
                    winnerName: winner?.name,
                    score: `${score1} - ${score2}`,
                    decision: winType
                });
            } catch(e) {}
        }

        // Trigger window storage event so draws-app iframe updates immediately
        try {
            window.dispatchEvent(new Event('storage'));
        } catch(e) {}

        return { targetMatch, winner, curBrackets };
    }

// 5.5. OFFICIAL JURY SECTION: COURT MATCH SCHEDULING & BOUT SCORING DESK
    // ========================================================================
    function renderJurySection(container, selectedCourt = '1') {
        const tournaments = store.getTournaments ? store.getTournaments() : [];
        const selectedTournId = store.getSelectedTournamentId ? store.getSelectedTournamentId() : null;
        const activeTourn = (store.getTournament && selectedTournId) ? (store.getTournament(selectedTournId) || tournaments[0] || {}) : (tournaments[0] || {});
        const compTitle = activeTourn.title || '48TH STATE LEVEL TAEKWONDO CHAMPIONSHIP 2026';

        // Auto-run sync so Draws Engine and Jury section use the latest scale-passed roster
        if (typeof window.syncTournamentAthletesToDraws === 'function') {
            try { window.syncTournamentAthletesToDraws(false); } catch(e) {}
        }

        // 1. Load active brackets from storage
        let brackets = {};
        try {
            brackets = JSON.parse(localStorage.getItem('tkd_brackets_v3') || '{}');
        } catch(e) {}

        // 2. Load court assignments
        let divisionCourts = {};
        try {
            divisionCourts = JSON.parse(localStorage.getItem('tkd_division_courts_v1') || '{}');
        } catch(e) {}

        // 3. Load active scale-passed competitors and divisions matching draws-app
        let competitors = [];
        try {
            competitors = JSON.parse(localStorage.getItem('tkd_competitors_v3') || '[]');
        } catch(e) {}

        const athletes = store.getAthletes ? store.getAthletes() : [];
        const passedAthletes = athletes.filter(a => {
            const s = (a.status || '').toString().trim().toLowerCase();
            const ws = (a.weighInStatus || '').toString().trim().toLowerCase();
            return s === 'passed' || ws === 'passed';
        });

        // Group competitors by division matching draws-app
        const divisionsMap = {};
        const sourceList = (competitors && competitors.length > 0) ? competitors : passedAthletes;
        sourceList.forEach(a => {
            const age = a.ageCategory || a.category || 'Junior';
            const gender = a.gender || 'Male';
            const wt = a.weightClass || 'U-55 kg';
            const divKey = (age + '_' + gender + '_' + wt).replace(/\s+/g, '_');
            const divName = `${age} ${gender} ${wt}`;
            if (!divisionsMap[divKey]) {
                divisionsMap[divKey] = { id: divKey, name: divName, athletes: [] };
            }
            divisionsMap[divKey].athletes.push(a);
        });

        // Also incorporate any existing division keys in brackets
        Object.keys(brackets).forEach(divKey => {
            if (!divisionsMap[divKey]) {
                divisionsMap[divKey] = { id: divKey, name: divKey.replace(/_/g, ' '), athletes: [] };
            }
        });

        // Canonical bracket generator matching draws-app exactly
        function generateCanonicalBracket(divKey, athletes) {
            if (!athletes || athletes.length < 2) return [];
            let seenE = new Set();
            const clean = (athletes || []).filter(x => {
                let k = (x.name || '').trim().toLowerCase();
                if (!k || seenE.has(k)) return false;
                seenE.add(k);
                return true;
            });
            if (clean.length < 2) return [];

            let t = clean.length, n = 2;
            for (; n < t;) n *= 2;

            // Separate academies and seeds (matching draws-app T)
            let nArray = Array(n).fill(null);
            let r = [...clean];
            for (let e = r.length - 1; e > 0; e--) {
                let idx = Math.floor(Math.random() * (e + 1));
                [r[e], r[idx]] = [r[idx], r[e]];
            }
            let i = {};
            r.forEach(e => {
                let club = (e.club || e.dojangName || 'Independent').trim(), lc = club.toLowerCase();
                if (!i[lc]) i[lc] = { name: club, members: [] };
                i[lc].members.push(e);
            });
            Object.values(i).forEach(e => {
                let members = e.members;
                for (let idx = members.length - 1; idx > 0; idx--) {
                    let sw = Math.floor(Math.random() * (idx + 1));
                    [members[idx], members[sw]] = [members[sw], members[idx]];
                }
            });
            let a = Object.values(i).sort((e, t) => {
                let diff = t.members.length - e.members.length;
                return diff === 0 ? Math.random() - 0.5 : diff;
            });
            let o = Math.log2(n), s = [];
            for (let e = 0; e < n; e++) {
                let val = 0;
                for (let bit = 0; bit < o; bit++) {
                    if ((e >> bit) & 1) val |= 1 << (o - 1 - bit);
                }
                s.push(val);
            }
            let c = Math.floor(Math.random() * n);
            let l = s.map(e => (e + c) % n), u = [], d = true, f = 0;
            while (d) {
                d = false;
                a.forEach(e => {
                    if (f < e.members.length) {
                        u.push(e.members[f]);
                        d = true;
                    }
                });
                f++;
            }
            for (let e = 0; e < u.length; e++) {
                nArray[l[e]] = u[e];
            }

            // Bracket rounds building
            let rounds = [], aRounds = n / 2, oRounds = 0;
            while (aRounds >= 1) {
                let roundMatches = [];
                for (let t = 0; t < aRounds; t++) {
                    roundMatches.push({
                        id: `match_${oRounds}_${t}`,
                        p1: null,
                        p2: null,
                        score1: null,
                        score2: null,
                        winnerId: null,
                        winType: null,
                        status: 'pending',
                        roundIndex: oRounds,
                        matchIndex: t,
                        nextMatchId: aRounds > 1 ? `match_${oRounds + 1}_${Math.floor(t / 2)}` : null,
                        nextMatchPosition: t % 2 === 0 ? 'p1' : 'p2'
                    });
                }
                rounds.push(roundMatches);
                aRounds /= 2;
                oRounds++;
            }

            let firstRound = rounds[0];
            for (let e = 0; e < firstRound.length; e++) {
                let match = firstRound[e];
                match.p1 = nArray[e * 2] || null;
                match.p2 = nArray[e * 2 + 1] || null;
                if (match.p1 && !match.p2) {
                    match.winnerId = match.p1.id;
                    match.status = 'walkover';
                } else if (!match.p1 && match.p2) {
                    match.winnerId = match.p2.id;
                    match.status = 'walkover';
                } else if (!match.p1 && !match.p2) {
                    match.status = 'walkover';
                }
            }

            // Advance walkovers and set match numbers
            advanceWalkoversInTree(rounds);
            assignMatchNumbers(rounds);
            return rounds;
        }

        function advanceWalkoversInTree(rounds) {
            if (!rounds || rounds.length === 0) return;
            for (let t = 1; t < rounds.length; t++) {
                for (let m of rounds[t]) {
                    m.p1 = null;
                    m.p2 = null;
                    if (m.status !== 'completed') {
                        m.winnerId = null;
                        m.status = 'pending';
                    }
                }
            }
            for (let t = 0; t < rounds.length; t++) {
                let curr = rounds[t], next = rounds[t + 1];
                for (let m of curr) {
                    if (t === 0) {
                        if (m.p1 && !m.p2) { m.winnerId = m.p1.id; m.status = 'walkover'; }
                        else if (!m.p1 && m.p2) { m.winnerId = m.p2.id; m.status = 'walkover'; }
                        else if (!m.p1 && !m.p2) { m.status = 'walkover'; }
                    }
                    if (m.winnerId && next) {
                        let nextM = next[Math.floor(m.matchIndex / 2)];
                        let winnerComp = m.winnerId === m.p1?.id ? m.p1 : m.p2;
                        if (nextM) {
                            if (m.matchIndex % 2 === 0) nextM.p1 = winnerComp;
                            else nextM.p2 = winnerComp;
                        }
                    }
                }
            }
            for (let t = 0; t < rounds.length - 1; t++) {
                let next = rounds[t + 1];
                for (let m of next) {
                    if (m.status === 'pending') {
                        let topFeeder = rounds[t][m.matchIndex * 2];
                        let btmFeeder = rounds[t][m.matchIndex * 2 + 1];
                        let topActive = topFeeder && (topFeeder.p1 || topFeeder.p2);
                        let btmActive = btmFeeder && (btmFeeder.p1 || btmFeeder.p2);
                        if (m.p1 && !btmActive) { m.winnerId = m.p1.id; m.status = 'walkover'; }
                        else if (m.p2 && !topActive) { m.winnerId = m.p2.id; m.status = 'walkover'; }
                        else if (!topActive && !btmActive) { m.status = 'walkover'; }
                    }
                }
            }
            for (let t = 0; t < rounds.length - 1; t++) {
                let curr = rounds[t], next = rounds[t + 1];
                for (let m of curr) {
                    if (m.winnerId && next) {
                        let nextM = next[Math.floor(m.matchIndex / 2)];
                        let winnerComp = m.winnerId === m.p1?.id ? m.p1 : m.p2;
                        if (nextM) {
                            if (m.matchIndex % 2 === 0) nextM.p1 = winnerComp;
                            else nextM.p2 = winnerComp;
                        }
                    }
                }
            }
        }

        function assignMatchNumbers(rounds) {
            let count = 1;
            for (let r = 0; r < rounds.length; r++) {
                for (let m = 0; m < rounds[r].length; m++) {
                    let match = rounds[r][m];
                    if (match.status === 'walkover') {
                        match.matchNo = null;
                    } else {
                        match.matchNo = count++;
                    }
                }
            }
        }

        // If brackets are empty or missing for active divisions, auto-generate canonical brackets
        let updatedBrackets = false;
        Object.keys(divisionsMap).forEach(divKey => {
            if (!brackets[divKey] || !Array.isArray(brackets[divKey]) || brackets[divKey].length === 0) {
                const aths = divisionsMap[divKey].athletes;
                if (aths.length >= 2) {
                    brackets[divKey] = generateCanonicalBracket(divKey, aths);
                    updatedBrackets = true;
                }
            }
        });

        if (updatedBrackets) {
            try {
                localStorage.setItem('tkd_brackets_v3', JSON.stringify(brackets));
                localStorage.setItem('tkd_match_updated', Date.now().toString());
            } catch(e) {}
        }

        // Ensure default court distribution if unassigned
        const divKeys = Object.keys(brackets);
        let updatedCourts = false;
        if (divKeys.length > 0) {
            divKeys.forEach((k, idx) => {
                if (!divisionCourts[k]) {
                    divisionCourts[k] = String((idx % 4) + 1);
                    updatedCourts = true;
                }
            });
            if (updatedCourts) {
                try {
                    localStorage.setItem('tkd_division_courts_v1', JSON.stringify(divisionCourts));
                } catch(e) {}
            }
        }

        // Helper: Stage order calculation (All R32 -> R16 -> Quarterfinals -> Semifinals -> Finals)
        function getStageInfo(roundIdx, totalRounds) {
            const dist = totalRounds - 1 - roundIdx;
            if (dist === 0) return { order: 5, name: 'Final' };
            if (dist === 1) return { order: 4, name: 'Semifinal' };
            if (dist === 2) return { order: 3, name: 'Quarterfinal' };
            if (dist === 3) return { order: 2, name: 'Round of 16' };
            if (dist === 4) return { order: 1, name: 'Round of 32' };
            return { order: 0, name: `Round ${roundIdx + 1}` };
        }

        // Helper: Resolve feeder match winner label (e.g. W1, W2) for downstream rounds
        function getFeederMatchLabel(rounds, rIdx, mIdx, isChong) {
            if (rIdx === 0) return 'TBD';
            const prevRound = rounds[rIdx - 1];
            if (!prevRound) return 'TBD';
            const feederIdx = mIdx * 2 + (isChong ? 0 : 1);
            const feederMatch = prevRound[feederIdx];
            if (feederMatch) {
                if (feederMatch.status === 'walkover' && feederMatch.winnerId) {
                    const winner = (feederMatch.p1 && feederMatch.p1.id === feederMatch.winnerId) ? feederMatch.p1 : (feederMatch.p2 || feederMatch.p1);
                    if (winner && winner.name) return winner.name;
                }
                if (feederMatch.matchNo) {
                    return `W${feederMatch.matchNo}`;
                }
            }
            return 'TBD';
        }

        // Filter divisions assigned to selectedCourt
        const assignedDivKeys = divKeys.filter(k => {
            if (selectedCourt === 'all') return true;
            return String(divisionCourts[k] || '1') === String(selectedCourt);
        });

        const scheduledMatches = [];

        assignedDivKeys.forEach(divKey => {
            const rounds = brackets[divKey];
            if (!Array.isArray(rounds)) return;
            const divObj = divisionsMap[divKey];
            const divName = divObj ? divObj.name : divKey.replace(/_/g, ' ');

            rounds.forEach((round, rIdx) => {
                if (!Array.isArray(round)) return;
                const stage = getStageInfo(rIdx, rounds.length);

                round.forEach((m, mIdx) => {
                    // STRICT WT RULE: Walkovers (byes) are automatic advancements, NEVER ring matches!
                    if (m.status === 'walkover') return;

                    const chongAthlete = m.p1;
                    const hongAthlete = m.p2;

                    const chongName = chongAthlete ? chongAthlete.name : getFeederMatchLabel(rounds, rIdx, m.matchIndex !== undefined ? m.matchIndex : mIdx, true);
                    const hongName = hongAthlete ? hongAthlete.name : getFeederMatchLabel(rounds, rIdx, m.matchIndex !== undefined ? m.matchIndex : mIdx, false);

                    const chongClub = chongAthlete ? (chongAthlete.club || chongAthlete.dojangName || '') : '';
                    const hongClub = hongAthlete ? (hongAthlete.club || hongAthlete.dojangName || '') : '';

                    const isChongPlaceholder = !chongAthlete;
                    const isHongPlaceholder = !hongAthlete;
                    const isReadyToFight = !!(chongAthlete && hongAthlete);

                    scheduledMatches.push({
                        divisionId: divKey,
                        divisionName: divName,
                        roundIndex: rIdx,
                        matchIndex: m.matchIndex !== undefined ? m.matchIndex : mIdx,
                        stageOrder: stage.order,
                        stageName: stage.name,
                        match: m,
                        p1: chongAthlete,
                        p2: hongAthlete,
                        chongName: chongName,
                        hongName: hongName,
                        chongClub: chongClub,
                        hongClub: hongClub,
                        isChongPlaceholder: isChongPlaceholder,
                        isHongPlaceholder: isHongPlaceholder,
                        isReadyToFight: isReadyToFight,
                        courtNo: divisionCourts[divKey] || '1'
                    });
                });
            });
        });

        // STRICT TAWEKWONDO PROGRESSION:
        // First all Round of 16, then Quarterfinals, then Semifinals, then Finals across all sheets!
        scheduledMatches.sort((a, b) => {
            if (a.stageOrder !== b.stageOrder) {
                return a.stageOrder - b.stageOrder;
            }
            if (a.divisionId !== b.divisionId) {
                return a.divisionId.localeCompare(b.divisionId);
            }
            return (a.matchIndex || 0) - (b.matchIndex || 0);
        });

        // Number matches sequentially
        scheduledMatches.forEach((sm, idx) => {
            sm.displayMatchNo = `Match No ${(idx + 1).toString().padStart(2, '0')}`;
            sm.seqIndex = idx + 1;
        });

        // Render main view
        container.innerHTML = `
            <div class="space-y-6 animate-fade-in w-full py-4 max-w-5xl mx-auto" id="tkd-jury-main-container">
                <!-- Top Actions Bar -->
                <div class="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-3 no-print">
                    <div class="flex items-center gap-2">
                        <span class="tkd-badge tkd-badge-blue text-[10px] uppercase font-bold tracking-wider">
                            <i class="fa-solid fa-gavel me-1"></i>Official Jury Section
                        </span>
                        <span class="text-xs text-slate-500 font-semibold">Live Bout Scoring &amp; Ring Allocations</span>
                    </div>
                    <div class="flex items-center gap-2">
                        <button class="tkd-btn tkd-btn-sm tkd-btn-outline font-bold text-xs" onclick="window.printJuryMatchSheet ? window.printJuryMatchSheet() : window.print()">
                            <i class="fa-solid fa-print me-1.5 text-blue-600"></i>Print Match Sheet
                        </button>
                        <button class="tkd-btn tkd-btn-sm tkd-btn-primary font-bold text-xs" id="btn-jury-view-draws">
                            <i class="fa-solid fa-sitemap me-1.5"></i>View Live Draws
                        </button>
                    </div>
                </div>

                <!-- Official Jury Sheet Printable Area (Matching Reference Image 1) -->
                <div id="tkd-jury-printable-area" class="jury-sheet-card">
                    <div class="jury-sheet-header">
                        <h1 class="jury-comp-title">${compTitle}</h1>
                        <div class="jury-court-selector-wrap">
                            <span class="font-extrabold text-slate-800 text-sm md:text-base">Court No –</span>
                            <select id="jury-court-select" class="jury-court-select" title="Choose Ring / Court Number">
                                <option value="1" ${selectedCourt === '1' ? 'selected' : ''}>01</option>
                                <option value="2" ${selectedCourt === '2' ? 'selected' : ''}>02</option>
                                <option value="3" ${selectedCourt === '3' ? 'selected' : ''}>03</option>
                                <option value="4" ${selectedCourt === '4' ? 'selected' : ''}>04</option>
                                <option value="all" ${selectedCourt === 'all' ? 'selected' : ''}>All Courts</option>
                            </select>
                        </div>
                    </div>

                    <!-- Official Matches Table Matching Reference Image 1 -->
                    <div class="jury-official-table-wrap">
                        ${scheduledMatches.length === 0 ? `
                            <div class="text-center py-12 px-4 bg-slate-50 border-2 border-dashed border-slate-300 rounded-xl">
                                <i class="fa-solid fa-calendar-xmark text-3xl text-slate-400 mb-2"></i>
                                <h3 class="text-sm font-bold text-slate-700">No Matches Assigned to Court ${selectedCourt}</h3>
                                <p class="text-xs text-slate-500 mt-1">Please ensure championship brackets are generated in Draws or choose another court from the dropdown above.</p>
                            </div>
                        ` : `
                            <table class="jury-official-table" id="tkd-jury-sheet-table">
                                <thead>
                                    <tr>
                                        <th style="width: 18%;">No.</th>
                                        <th style="width: 31%;">Chong Player</th>
                                        <th style="width: 31%;">Hong Player</th>
                                        <th style="width: 20%;">Results</th>
                                    </tr>
                                </thead>
                                <tbody>
                                    ${scheduledMatches.map(sm => {
                                        const m = sm.match;
                                        const isCompleted = m.status === 'completed';
                                        const winnerIsChong = isCompleted && m.winnerId === m.p1?.id;
                                        const winnerIsHong = isCompleted && m.winnerId === m.p2?.id;

                                        return `
                                            <tr data-match-id="${m.id}" data-div-id="${sm.divisionId}">
                                                <td class="jury-match-no">
                                                    <div>${sm.displayMatchNo}</div>
                                                    <div class="text-[10px] text-slate-500 font-semibold uppercase mt-0.5 tracking-wide">
                                                        ${sm.divisionName} • ${sm.stageName}
                                                    </div>
                                                </td>
                                                <td>
                                                    ${sm.isChongPlaceholder ? `
                                                        <span class="jury-feeder-placeholder">${sm.chongName}</span>
                                                        <div class="jury-feeder-sub">Awaiting previous match</div>
                                                    ` : `
                                                        <span class="jury-player-chong ${winnerIsChong ? 'underline decoration-blue-500 decoration-2' : ''}">${sm.chongName}</span>
                                                        ${sm.chongClub ? `<div class="text-[10px] text-slate-500 font-normal mt-0.5">${sm.chongClub}</div>` : ''}
                                                    `}
                                                </td>
                                                <td>
                                                    ${sm.isHongPlaceholder ? `
                                                        <span class="jury-feeder-placeholder" style="color: #E11D48;">${sm.hongName}</span>
                                                        <div class="jury-feeder-sub">Awaiting previous match</div>
                                                    ` : `
                                                        <span class="jury-player-hong ${winnerIsHong ? 'underline decoration-red-500 decoration-2' : ''}">${sm.hongName}</span>
                                                        ${sm.hongClub ? `<div class="text-[10px] text-slate-500 font-normal mt-0.5">${sm.hongClub}</div>` : ''}
                                                    `}
                                                </td>
                                                <td>
                                                    <div class="flex items-center gap-1.5 flex-wrap">
                                                        ${isCompleted ? `
                                                            <span class="jury-result-badge ${winnerIsChong ? 'bg-blue-50 text-blue-700 border border-blue-200' : 'bg-red-50 text-red-700 border border-red-200'}">
                                                                ${m.score1 ?? 0}-${m.score2 ?? 0} (${m.winType || 'WPS'})
                                                            </span>
                                                            <button class="jury-btn-update no-print" data-action="update-match" data-div-id="${sm.divisionId}" data-match-id="${m.id}" data-match-no="${sm.displayMatchNo}" data-stage-name="${sm.stageName}" data-div-name="${sm.divisionName}" data-court-no="${sm.courtNo}" title="Manually edit or view match scores">
                                                                <i class="fa-solid fa-pen-to-square text-[11px]"></i>Update
                                                            </button>
                                                            <button class="jury-btn-reconduct no-print" data-action="conduct-match" data-div-id="${sm.divisionId}" data-match-id="${m.id}" data-match-no="${sm.displayMatchNo}" data-stage-name="${sm.stageName}" data-div-name="${sm.divisionName}" data-court-no="${sm.courtNo}" title="Re-conduct match in Electronic Scoring System (ESS)">
                                                                <i class="fa-solid fa-play text-[11px]"></i>Re-Conduct
                                                            </button>
                                                        ` : sm.isReadyToFight ? `
                                                            <button class="jury-btn-conduct no-print" data-action="conduct-match" data-div-id="${sm.divisionId}" data-match-id="${m.id}" data-match-no="${sm.displayMatchNo}" data-stage-name="${sm.stageName}" data-div-name="${sm.divisionName}" data-court-no="${sm.courtNo}" title="Open ESS directly with competitors preloaded">
                                                                <i class="fa-solid fa-play text-[11px]"></i>Conduct Match
                                                            </button>
                                                            <button class="jury-btn-update no-print" data-action="update-match" data-div-id="${sm.divisionId}" data-match-id="${m.id}" data-match-no="${sm.displayMatchNo}" data-stage-name="${sm.stageName}" data-div-name="${sm.divisionName}" data-court-no="${sm.courtNo}" title="Manually type and upload scores">
                                                                <i class="fa-solid fa-pen-to-square text-[11px]"></i>Update
                                                            </button>
                                                        ` : `
                                                            <button class="jury-btn-pending no-print" disabled title="Awaiting completion of earlier round matches">
                                                                <i class="fa-solid fa-hourglass-half text-[10px]"></i>Pending ${sm.isChongPlaceholder ? sm.chongName : sm.hongName}
                                                            </button>
                                                        `}
                                                    </div>
                                                </td>
                                            </tr>
                                        `;
                                    }).join('')}
                                </tbody>
                            </table>
                        `}
                    </div>
                </div>
            </div>
        `;

        // Event: Court selector change
        const courtSelect = document.getElementById('jury-court-select');
        if (courtSelect) {
            courtSelect.onchange = (e) => {
                renderJurySection(container, e.target.value);
            };
        }

        // Event: View Live Draws button
        const btnViewDraws = document.getElementById('btn-jury-view-draws');
        if (btnViewDraws) {
            btnViewDraws.onclick = () => {
                if (window.app && typeof window.app.navigate === 'function') {
                    window.app.navigate('draws');
                }
            };
        }

        // Event: Update buttons on match rows
        container.querySelectorAll('[data-action="update-match"]').forEach(btn => {
            btn.onclick = () => {
                const divId = btn.getAttribute('data-div-id');
                const matchId = btn.getAttribute('data-match-id');
                const displayMatchNo = btn.getAttribute('data-match-no');
                const stageName = btn.getAttribute('data-stage-name');
                const divisionName = btn.getAttribute('data-div-name');
                const courtNo = btn.getAttribute('data-court-no') || selectedCourt;

                // Find match object
                let matchObj = null;
                if (brackets[divId] && Array.isArray(brackets[divId])) {
                    for (let r = 0; r < brackets[divId].length; r++) {
                        const found = brackets[divId][r].find(m => m.id === matchId);
                        if (found) {
                            matchObj = found;
                            break;
                        }
                    }
                }

                if (!matchObj) {
                    alert('Match record not found in active brackets.');
                    return;
                }

                if (!matchObj.p1 || !matchObj.p2) {
                    alert('Both competitors must be determined before recording match scores. Please complete earlier round matches.');
                    return;
                }

                openJuryScoringModal({
                    compTitle: compTitle,
                    courtNo: courtNo,
                    displayMatchNo: displayMatchNo,
                    stageName: stageName,
                    divisionName: divisionName,
                    divisionId: divId,
                    match: matchObj
                }, (winnerId, s1, s2, winType, roundScores) => {
                    handleSaveJuryScore(divId, matchId, winnerId, s1, s2, winType, roundScores);
                });
            };
        });

        // Event: Conduct Match buttons on match rows (Opens ESS directly with competitors preloaded)
        container.querySelectorAll('[data-action="conduct-match"]').forEach(btn => {
            btn.onclick = () => {
                const divId = btn.getAttribute('data-div-id');
                const matchId = btn.getAttribute('data-match-id');
                const displayMatchNo = btn.getAttribute('data-match-no');
                const stageName = btn.getAttribute('data-stage-name');
                const divisionName = btn.getAttribute('data-div-name');
                const courtNo = btn.getAttribute('data-court-no') || selectedCourt;

                // Find match object
                let matchObj = null;
                if (brackets[divId] && Array.isArray(brackets[divId])) {
                    for (let r = 0; r < brackets[divId].length; r++) {
                        const found = brackets[divId][r].find(m => m.id === matchId);
                        if (found) {
                            matchObj = found;
                            break;
                        }
                    }
                }

                if (!matchObj) {
                    alert('Match record not found in active brackets.');
                    return;
                }

                if (!matchObj.p1 || !matchObj.p2) {
                    alert('Both competitors must be determined before conducting match. Please complete earlier round matches.');
                    return;
                }

                openConductMatchModal({
                    compTitle: compTitle,
                    courtNo: courtNo,
                    displayMatchNo: displayMatchNo,
                    stageName: stageName,
                    divisionName: divisionName,
                    divisionId: divId,
                    match: matchObj,
                    onManualScore: () => {
                        openJuryScoringModal({
                            compTitle: compTitle,
                            courtNo: courtNo,
                            displayMatchNo: displayMatchNo,
                            stageName: stageName,
                            divisionName: divisionName,
                            divisionId: divId,
                            match: matchObj
                        }, (winnerId, s1, s2, winType, roundScores) => {
                            handleSaveJuryScore(divId, matchId, winnerId, s1, s2, winType, roundScores);
                        });
                    }
                }, (syncData) => {
                    handleSaveJuryScore(divId, matchId, syncData.winnerId, syncData.score1, syncData.score2, syncData.winType, syncData.roundScores);
                });
            };
        });

        // Helper: Save and advance match in brackets
        function handleSaveJuryScore(divId, matchId, winnerId, score1, score2, winType, roundScores) {
            applyBracketMatchScore(divId, matchId, winnerId, score1, score2, winType, roundScores);
            // Re-render Jury court sheet with updated results and next matches populated!
            renderJurySection(container, selectedCourt);
        }
        window.handleSaveJuryScore = handleSaveJuryScore;
    }

    // Modal: Jury Best-of-3 Scoring Modal (Matching Reference Image 2)
    function openJuryScoringModal(data, onSave) {
        const modalId = 'tkd-jury-scoring-modal';
        document.getElementById(modalId)?.remove();

        const match = data.match;
        const p1 = match.p1 || { id: 'p1_temp', name: 'Chong Player', club: 'Academy' };
        const p2 = match.p2 || { id: 'p2_temp', name: 'Hong Player', club: 'Academy' };
        const roundScores = match.roundScores || [
            { blue: null, red: null, blueGamjeom: 0, redGamjeom: 0 },
            { blue: null, red: null, blueGamjeom: 0, redGamjeom: 0 },
            { blue: null, red: null, blueGamjeom: 0, redGamjeom: 0 }
        ];
        let currentWinType = match.winType || 'WPS';

        const modalDiv = document.createElement('div');
        modalDiv.id = modalId;
        modalDiv.className = 'jury-modal-overlay';
        modalDiv.innerHTML = `
            <div class="jury-modal-container" role="dialog" aria-modal="true">
                <button type="button" class="absolute top-4 right-4 text-slate-400 hover:text-slate-700 text-xl font-bold p-1 cursor-pointer" id="btn-jury-modal-close" title="Close">
                    <i class="fa-solid fa-xmark"></i>
                </button>

                <!-- Title & Subtitle Matching Image 2 -->
                <h2 class="jury-modal-title">${data.compTitle || '48TH STATE LEVEL TAEKWONDO CHAMPIONSHIP 2026'}</h2>
                <p class="jury-modal-subtitle">Court No – ${(String(data.courtNo) || '1').padStart(2, '0')} • ${data.displayMatchNo} • ${data.divisionName} • ${data.stageName}</p>

                <!-- Dual Color Banners: Chong (Blue) & Hong (Red) -->
                <div class="jury-banners-row">
                    <div class="jury-banner-chong">
                        <span class="truncate">${p1.name}</span>
                    </div>
                    <div class="jury-banner-hong">
                        <span class="truncate">${p2.name}</span>
                    </div>
                </div>

                <!-- Best-of-3 Score Arena + Gam-jeom Boxes (Matching Image 2) -->
                <div class="jury-score-arena">
                    <!-- Left: Chong Gam-jeom (3 boxes) -->
                    <div class="jury-gamjeom-col">
                        <div class="jury-gamjeom-header-chong">Gam-jeom</div>
                        <div class="jury-gamjeom-box" title="Round 1 Chong Gam-jeom">
                            <input type="number" min="0" max="5" class="jury-gamjeom-input" id="jury-gj-chong-r1" value="${roundScores[0]?.blueGamjeom || 0}">
                        </div>
                        <div class="jury-gamjeom-box" title="Round 2 Chong Gam-jeom">
                            <input type="number" min="0" max="5" class="jury-gamjeom-input" id="jury-gj-chong-r2" value="${roundScores[1]?.blueGamjeom || 0}">
                        </div>
                        <div class="jury-gamjeom-box" title="Round 3 Chong Gam-jeom">
                            <input type="number" min="0" max="5" class="jury-gamjeom-input" id="jury-gj-chong-r3" value="${roundScores[2]?.blueGamjeom || 0}">
                        </div>
                    </div>

                    <!-- Center: 2x3 Round Scores Grid -->
                    <div class="jury-score-grid-wrap">
                        <table class="jury-score-grid">
                            <thead>
                                <tr>
                                    <th style="width: 30%;">Round</th>
                                    <th style="width: 35%; color: #0052FF;">Chong (Blue)</th>
                                    <th style="width: 35%; color: #DC2626;">Hong (Red)</th>
                                </tr>
                            </thead>
                            <tbody>
                                <tr>
                                    <td class="font-bold text-xs text-slate-700 uppercase">Round 1</td>
                                    <td>
                                        <input type="number" min="0" max="99" class="jury-round-score-input chong-score" id="jury-score-chong-r1" value="${roundScores[0]?.blue ?? ''}" placeholder="0">
                                    </td>
                                    <td>
                                        <input type="number" min="0" max="99" class="jury-round-score-input hong-score" id="jury-score-hong-r1" value="${roundScores[0]?.red ?? ''}" placeholder="0">
                                    </td>
                                </tr>
                                <tr>
                                    <td class="font-bold text-xs text-slate-700 uppercase">Round 2</td>
                                    <td>
                                        <input type="number" min="0" max="99" class="jury-round-score-input chong-score" id="jury-score-chong-r2" value="${roundScores[1]?.blue ?? ''}" placeholder="0">
                                    </td>
                                    <td>
                                        <input type="number" min="0" max="99" class="jury-round-score-input hong-score" id="jury-score-hong-r2" value="${roundScores[1]?.red ?? ''}" placeholder="0">
                                    </td>
                                </tr>
                                <tr>
                                    <td class="font-bold text-xs text-slate-700 uppercase">Round 3</td>
                                    <td>
                                        <input type="number" min="0" max="99" class="jury-round-score-input chong-score" id="jury-score-chong-r3" value="${roundScores[2]?.blue ?? ''}" placeholder="0">
                                    </td>
                                    <td>
                                        <input type="number" min="0" max="99" class="jury-round-score-input hong-score" id="jury-score-hong-r3" value="${roundScores[2]?.red ?? ''}" placeholder="0">
                                    </td>
                                </tr>
                            </tbody>
                        </table>
                    </div>

                    <!-- Right: Hong Gam-jeom (3 boxes) -->
                    <div class="jury-gamjeom-col">
                        <div class="jury-gamjeom-header-hong">Gam-jeom</div>
                        <div class="jury-gamjeom-box" title="Round 1 Hong Gam-jeom">
                            <input type="number" min="0" max="5" class="jury-gamjeom-input" id="jury-gj-hong-r1" value="${roundScores[0]?.redGamjeom || 0}">
                        </div>
                        <div class="jury-gamjeom-box" title="Round 2 Hong Gam-jeom">
                            <input type="number" min="0" max="5" class="jury-gamjeom-input" id="jury-gj-hong-r2" value="${roundScores[1]?.redGamjeom || 0}">
                        </div>
                        <div class="jury-gamjeom-box" title="Round 3 Hong Gam-jeom">
                            <input type="number" min="0" max="5" class="jury-gamjeom-input" id="jury-gj-hong-r3" value="${roundScores[2]?.redGamjeom || 0}">
                        </div>
                    </div>
                </div>

                <!-- Decision Selector (PTG | WPS | PUN | RSC | ABC) Matching Image 2 -->
                <div class="jury-decision-section">
                    <div class="jury-decision-title">WT Victory Declaration / Decision Type</div>
                    <div class="jury-decision-grid">
                        <button type="button" class="jury-decision-btn ${currentWinType === 'PTG' ? 'active' : ''}" data-win-type="PTG" title="Point Gap (12-point margin)">PTG</button>
                        <button type="button" class="jury-decision-btn ${currentWinType === 'WPS' ? 'active' : ''}" data-win-type="WPS" title="Win by Points / Superiority">WPS</button>
                        <button type="button" class="jury-decision-btn ${currentWinType === 'PUN' ? 'active' : ''}" data-win-type="PUN" title="Win by Punitive Declaration (5 Gam-jeom)">PUN</button>
                        <button type="button" class="jury-decision-btn ${currentWinType === 'RSC' ? 'active' : ''}" data-win-type="RSC" title="Referee Stops Contest">RSC</button>
                        <button type="button" class="jury-decision-btn ${currentWinType === 'ABC' ? 'active' : ''}" data-win-type="ABC" title="Abandon / Competitor Withdrawal">ABC</button>
                    </div>
                </div>

                <!-- Winner Selection & Summary -->
                <div class="jury-winner-strip">
                    <div class="flex items-center gap-2">
                        <span class="text-xs font-black uppercase text-slate-500">Bout Outcome:</span>
                        <span id="jury-rounds-summary" class="text-xs font-bold text-slate-700">Rounds: Chong 0 - 0 Hong</span>
                    </div>
                    <div class="jury-winner-radios">
                        <label class="jury-winner-label chong">
                            <input type="radio" name="jury-winner-corner" value="chong" ${match.winnerId === p1.id ? 'checked' : ''}>
                            <span>${p1.name} (Chong)</span>
                        </label>
                        <label class="jury-winner-label hong">
                            <input type="radio" name="jury-winner-corner" value="hong" ${match.winnerId === p2.id ? 'checked' : ''}>
                            <span>${p2.name} (Hong)</span>
                        </label>
                    </div>
                </div>

                <!-- Action Controls -->
                <div class="jury-modal-actions">
                    <button type="button" class="tkd-btn tkd-btn-outline font-bold text-xs" id="btn-jury-modal-cancel">
                        Cancel
                    </button>
                    <button type="button" class="tkd-btn tkd-btn-primary font-bold text-xs shadow-sm" id="btn-jury-modal-save">
                        <i class="fa-solid fa-floppy-disk me-1.5"></i>Save &amp; Update Bracket
                    </button>
                </div>
            </div>
        `;

        document.body.appendChild(modalDiv);

        // Recalculate round wins live
        function recalculateScores() {
            const r1c = Number(document.getElementById('jury-score-chong-r1')?.value || 0);
            const r1h = Number(document.getElementById('jury-score-hong-r1')?.value || 0);
            const r2c = Number(document.getElementById('jury-score-chong-r2')?.value || 0);
            const r2h = Number(document.getElementById('jury-score-hong-r2')?.value || 0);
            const r3c = Number(document.getElementById('jury-score-chong-r3')?.value || 0);
            const r3h = Number(document.getElementById('jury-score-hong-r3')?.value || 0);

            let chongWins = 0;
            let hongWins = 0;

            const hasR1 = document.getElementById('jury-score-chong-r1')?.value !== '' && document.getElementById('jury-score-hong-r1')?.value !== '';
            const hasR2 = document.getElementById('jury-score-chong-r2')?.value !== '' && document.getElementById('jury-score-hong-r2')?.value !== '';
            const hasR3 = document.getElementById('jury-score-chong-r3')?.value !== '' && document.getElementById('jury-score-hong-r3')?.value !== '';

            if (hasR1) { if (r1c > r1h) chongWins++; else if (r1h > r1c) hongWins++; }
            if (hasR2) { if (r2c > r2h) chongWins++; else if (r2h > r2c) hongWins++; }
            if (hasR3) { if (r3c > r3h) chongWins++; else if (r3h > r3c) hongWins++; }

            const summaryEl = document.getElementById('jury-rounds-summary');
            if (summaryEl) {
                summaryEl.innerText = `Rounds: Chong ${chongWins} - ${hongWins} Hong`;
            }

            const rChong = document.querySelector('input[name="jury-winner-corner"][value="chong"]');
            const rHong = document.querySelector('input[name="jury-winner-corner"][value="hong"]');

            if (chongWins >= 2 && rChong) {
                rChong.checked = true;
            } else if (hongWins >= 2 && rHong) {
                rHong.checked = true;
            }
        }

        // Bind score input listeners
        ['jury-score-chong-r1', 'jury-score-hong-r1', 'jury-score-chong-r2', 'jury-score-hong-r2', 'jury-score-chong-r3', 'jury-score-hong-r3'].forEach(id => {
            const el = document.getElementById(id);
            if (el) el.addEventListener('input', recalculateScores);
        });

        recalculateScores();

        // Bind decision type selection buttons
        modalDiv.querySelectorAll('.jury-decision-btn').forEach(btn => {
            btn.onclick = () => {
                modalDiv.querySelectorAll('.jury-decision-btn').forEach(b => b.classList.remove('active'));
                btn.classList.add('active');
                currentWinType = btn.getAttribute('data-win-type') || 'WPS';
            };
        });

        // Close & Cancel buttons
        const closeModal = () => modalDiv.remove();
        document.getElementById('btn-jury-modal-close')?.addEventListener('click', closeModal);
        document.getElementById('btn-jury-modal-cancel')?.addEventListener('click', closeModal);
        modalDiv.addEventListener('click', (e) => {
            if (e.target === modalDiv) closeModal();
        });

        // Save & Update Bracket button
        document.getElementById('btn-jury-modal-save').onclick = () => {
            const winnerCorner = document.querySelector('input[name="jury-winner-corner"]:checked')?.value;
            if (!winnerCorner) {
                alert('Please designate the winning player before saving.');
                return;
            }

            const winnerId = (winnerCorner === 'chong') ? p1.id : p2.id;

            const r1c = document.getElementById('jury-score-chong-r1')?.value !== '' ? Number(document.getElementById('jury-score-chong-r1').value) : 0;
            const r1h = document.getElementById('jury-score-hong-r1')?.value !== '' ? Number(document.getElementById('jury-score-hong-r1').value) : 0;
            const r2c = document.getElementById('jury-score-chong-r2')?.value !== '' ? Number(document.getElementById('jury-score-chong-r2').value) : 0;
            const r2h = document.getElementById('jury-score-hong-r2')?.value !== '' ? Number(document.getElementById('jury-score-hong-r2').value) : 0;
            const r3c = document.getElementById('jury-score-chong-r3')?.value !== '' ? Number(document.getElementById('jury-score-chong-r3').value) : 0;
            const r3h = document.getElementById('jury-score-hong-r3')?.value !== '' ? Number(document.getElementById('jury-score-hong-r3').value) : 0;

            const r1cg = Number(document.getElementById('jury-gj-chong-r1')?.value || 0);
            const r1hg = Number(document.getElementById('jury-gj-hong-r1')?.value || 0);
            const r2cg = Number(document.getElementById('jury-gj-chong-r2')?.value || 0);
            const r2hg = Number(document.getElementById('jury-gj-hong-r2')?.value || 0);
            const r3cg = Number(document.getElementById('jury-gj-chong-r3')?.value || 0);
            const r3hg = Number(document.getElementById('jury-gj-hong-r3')?.value || 0);

            const compiledRoundScores = [
                { blue: r1c, red: r1h, blueGamjeom: r1cg, redGamjeom: r1hg },
                { blue: r2c, red: r2h, blueGamjeom: r2cg, redGamjeom: r2hg },
                { blue: r3c, red: r3h, blueGamjeom: r3cg, redGamjeom: r3hg }
            ];

            let blueWins = 0, redWins = 0;
            if (r1c > r1h) blueWins++; else if (r1h > r1c) redWins++;
            if (r2c > r2h) blueWins++; else if (r2h > r2c) redWins++;
            if (r3c > r3h) blueWins++; else if (r3h > r3c) redWins++;

            if (winnerCorner === 'chong' && blueWins <= redWins) blueWins = Math.max(2, redWins + 1);
            if (winnerCorner === 'hong' && redWins <= blueWins) redWins = Math.max(2, blueWins + 1);

            modalDiv.remove();
            onSave(winnerId, blueWins, redWins, currentWinType, compiledRoundScores);
        };
    }

    window.renderJurySection = renderJurySection;
    window.openJuryScoringModal = openJuryScoringModal;
