    // Global synchronization for matches completed in ESS (either embedded iframe or popout arena screen)
    function handleGlobalEssMatchCompletion(payload) {
        if (!payload || payload.type !== 'TKD_ESS_MATCH_COMPLETED') return;
        const matchId = payload.matchId;
        const divId = payload.divisionId;
        if (!matchId || !divId) return;

        let curBrackets = {};
        try {
            curBrackets = JSON.parse(localStorage.getItem('tkd_brackets_v3') || '{}');
        } catch(e) {}

        const rounds = curBrackets[divId];
        if (!rounds || !Array.isArray(rounds)) return;

        let targetMatch = null;
        for (let r = 0; r < rounds.length; r++) {
            const found = rounds[r].find(m => m.id === matchId);
            if (found) { targetMatch = found; break; }
        }
        if (!targetMatch) return;

        let winnerId = payload.winnerId;
        if (!winnerId) {
            winnerId = (payload.winner === 'blue') ? targetMatch.p1?.id : targetMatch.p2?.id;
        }

        // Check if already updated with same results to prevent redundant writes
        if (targetMatch.status === 'completed' && targetMatch.winnerId === winnerId && targetMatch.score1 === payload.score1 && targetMatch.score2 === payload.score2) {
            return;
        }

        const res = applyBracketMatchScore(divId, matchId, winnerId, payload.score1, payload.score2, payload.winType, payload.roundScores);

        const winnerName = res?.winner?.name || payload.winnerName || 'Winner';
        if (typeof showToast === 'function') {
            showToast(`🏆 ${payload.displayMatchNo || 'Match'} Concluded! ${winnerName} won (${payload.score1}-${payload.score2} ${payload.winType || 'WPS'}).`, 'success');
        }

        // Update modal banner if conduct modal is currently open
        const banner = document.getElementById('conduct-modal-sync-banner');
        const bannerText = document.getElementById('conduct-modal-sync-text');
        if (banner && bannerText) {
            bannerText.textContent = `Match concluded! Winner: ${winnerName} (${payload.score1}-${payload.score2} ${payload.winType || 'WPS'}).`;
            banner.classList.remove('hidden');
        }

        // Re-render Jury court sheet if currently visible
        const juryContainer = document.getElementById('tkd-jury-main-container');
        if (juryContainer && juryContainer.parentElement) {
            const courtSelect = document.getElementById('jury-court-select');
            const currentCourt = courtSelect ? courtSelect.value : (payload.courtNo || '1');
            renderJurySection(juryContainer.parentElement, currentCourt);
        }
    }

    // Register message and storage listeners for live ESS score sync
    window.addEventListener('message', (e) => {
        if (!e.data) return;
        if (e.data.type === 'TKD_ESS_MATCH_COMPLETED') {
            handleGlobalEssMatchCompletion(e.data);
        }
        if (e.data.type === 'TKD_ESS_CLOSE_CONDUCT_MODAL' || e.data === 'TKD_ESS_CLOSE_CONDUCT_MODAL') {
            if (typeof window.closeEssConductModal === 'function') {
                window.closeEssConductModal();
            } else {
                document.querySelectorAll('.jury-conduct-modal-overlay, #tkd-jury-conduct-modal').forEach(m => m.remove());
            }
        }
    });

    window.addEventListener('storage', (e) => {
        if (e.key === 'tkd_ess_match_completed' && e.newValue) {
            try {
                const data = JSON.parse(e.newValue);
                handleGlobalEssMatchCompletion(data);
            } catch(err) {}
        }
    });

    window.openConductMatchModal = openConductMatchModal;
    window.handleGlobalEssMatchCompletion = handleGlobalEssMatchCompletion;
    window.applyBracketMatchScore = applyBracketMatchScore;


